INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5900, 'SEM', '/ˌes iː ˈem/', 'noun', '{"zh-TW":["搜尋引擎行銷"],"en":["search engine marketing; paid advertising in search engine results"]}', NULL, 'SEM campaign / SEM strategy / implement SEM', '[{"en":"SEM complements SEO to maximize search visibility.","zh-TW":"SEM補充了SEO以最大化搜尋可見性。"},{"en":"She managed a $50,000 monthly SEM budget.","zh-TW":"她管理著每月5萬美元的SEM預算。"}]', '{"full form":"search engine marketing"}', NULL, 1, 5900, NULL),
(5901, 'semantics', '/''sɪˌmæntɪks/', 'noun', '{"zh-TW":["語義學；語意"],"en":["the branch of linguistics concerned with meaning; the meaning of words, phrases, or text"]}', NULL, 'study semantics / word semantics / semantic meaning', '[{"en":"The debate over semantics delayed the contract negotiations by several days.","zh-TW":"關於語義學的辯論使合同談判延遲了幾天。"},{"en":"Understanding semantics is important for developing natural language processing systems.","zh-TW":"理解語義學對於開發自然語言處理系統非常重要。"}]', '{"adjective":"semantic","adverb":"semantically"}', NULL, 3, 5901, NULL),
(5902, 'semester', '/sɪˈmɛstər/', 'noun', '{"zh-TW":["學期"],"en":["half of the school year","a half-year term in a school or university"]}', NULL, 'fall semester / spring semester; fall semester / spring semester / per semester', '[{"en":"The fall semester starts in August.","zh-TW":"秋季學期八月開始。"},{"en":"I''m taking five courses this semester.","zh-TW":"這學期我修了五門課。"},{"en":"The course runs for one semester.","zh-TW":"這門課程為期一個學期。"},{"en":"Registration for next semester starts in November.","zh-TW":"下學期的註冊在十一月開始。"}]', '{"noun":"semester"}', NULL, 3, 5902, NULL),
(5903, 'seminal', '/ˈsemɪnəl/', 'adjective', '{"zh-TW":["開創性的；奠基性的"],"en":["strongly influencing later developments; being a first of its kind"]}', NULL, 'seminal work / seminal paper / seminal study', '[{"en":"Darwin''s seminal work transformed the field of biology.","zh-TW":"達爾文的開創性著作改變了生物學領域。"},{"en":"This seminal article is cited in hundreds of research papers.","zh-TW":"這篇奠基性文章被數百篇研究論文引用。"}]', '{"adverb":"seminally"}', NULL, 3, 5903, NULL),
(5904, 'seminar', '/ˈsɛmɪnɑːr/', 'noun', '{"zh-TW":["研討會；小組討論課"],"en":["a small class for discussion or advanced study"]}', NULL, 'attend a seminar / academic seminar', '[{"en":"The seminar focused on global economic trends.","zh-TW":"研討會聚焦於全球經濟趨勢。"},{"en":"Participation in the seminar counts toward your final grade.","zh-TW":"參與研討會計入您的最終成績。"}]', NULL, NULL, 3, 5904, NULL),
(5905, 'seminar room', '/ˈsɛmɪnɑːr ruːm/', 'noun', '{"zh-TW":["研討室"],"en":["a room used for small group discussions and presentations"]}', NULL, 'reserve a seminar room / seminar room capacity', '[{"en":"The seminar room holds up to 30 participants.","zh-TW":"研討室最多可容納30名參與者。"},{"en":"The training was conducted in the ground-floor seminar room.","zh-TW":"培訓在一樓的研討室進行。"}]', NULL, NULL, 4, 5905, NULL),
(5906, 'senate', '/ˈsɛnɪt/', 'noun', '{"zh-TW":["參議院"],"en":["the upper house of a legislature"]}', NULL, 'senate vote / state senate', '[{"en":"The senate approved the bill.","zh-TW":"參議院批准了該法案。"},{"en":"She was elected to the senate.","zh-TW":"她被選入參議院。"}]', '{"noun2":"senator"}', NULL, 2, 5906, NULL),
(5907, 'send', '/sɛnd/', 'verb', '{"zh-TW":["發送；寄"],"en":["to cause to go to a destination"]}', NULL, 'send an email / send out', '[{"en":"I will send the document by email.","zh-TW":"我會用電子郵件寄文件。"},{"en":"We sent out 500 invitations.","zh-TW":"我們發出了500份邀請函。"}]', '{"verb":"send","noun":"sender"}', NULL, 1, 5907, NULL),
(5908, 'senior', '/ˈsiːnjər/', 'adjective, noun', '{"zh-TW":["資深的；年長的","前輩；上級"],"en":["higher in rank or longer in service","an older or higher-ranking person"]}', NULL, 'senior manager / senior staff / senior position', '[{"en":"She was promoted to senior manager.","zh-TW":"她被提升為資深經理。"},{"en":"Senior employees receive additional benefits.","zh-TW":"資深員工享有額外福利。"}]', '{"noun":"seniority, senior","adjective":"senior"}', NULL, 2, 5908, 452),
(5909, 'senior management', '/ˈsiːniər ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["高級管理層；高管"],"en":["the highest level of management in an organization"]}', NULL, 'consult senior management / senior management team', '[{"en":"Senior management approved the expansion into three new markets.","zh-TW":"高級管理層批准了進入三個新市場的擴張。"},{"en":"Decisions of this magnitude must be escalated to senior management.","zh-TW":"這種規模的決策必須升級至高級管理層。"}]', NULL, NULL, 5, 5909, NULL),
(5910, 'seniority', '/sɪˈnɪɒrɪti/', 'noun', '{"zh-TW":["資歷；職級"],"en":["the fact of being older or higher in rank"]}', NULL, 'based on seniority / seniority system', '[{"en":"Promotions in this company are based on seniority and merit.","zh-TW":"這家公司的晉升基於資歷和績效。"},{"en":"Her seniority earned her a reserved parking space.","zh-TW":"她的資歷為她贏得了一個保留車位。"}]', '{"adjective":"senior"}', NULL, 3, 5910, NULL),
(5911, 'seniority system', '/ˌsiːniˈɒrɪti ˈsɪstəm/', 'noun', '{"zh-TW":["資歷制度"],"en":["a system in which seniority determines promotions, pay, and layoffs"]}', NULL, 'apply a seniority system / seniority system in unions / dismantle the seniority system', '[{"en":"The seniority system guaranteed that long-serving employees would be the last to be laid off.","zh-TW":"資歷制度保證了長期服務的員工將是最後被裁員的。"},{"en":"Labor unions advocate for seniority systems to protect workers from arbitrary dismissal.","zh-TW":"勞工工會倡導資歷制度，以保護工人免受任意解僱。"}]', NULL, NULL, 5, 5911, NULL),
(5912, 'sense', '/sens/', 'noun, verb', '{"zh-TW":["感覺；意識","感覺到；意識到"],"en":["a feeling or awareness","to feel or be aware of"]}', NULL, 'make sense / common sense / sense of urgency', '[{"en":"It makes sense to start planning early.","zh-TW":"早點開始計畫是合理的。"},{"en":"She sensed that something was wrong.","zh-TW":"她感覺到有什麼不對勁。"}]', '{"noun":"sense, sensation","verb":"sense","adjective":"sensible, sensory"}', NULL, 2, 5912, NULL),
(5913, 'sensitive', '/ˈsensɪtɪv/', 'adjective', '{"zh-TW":["敏感的；善感的","敏感的；靈敏的","機密的"],"en":["easily affected by others'' feelings or external conditions","easily affected or offended","requiring careful handling"]}', '{"root":{"text":"sens","meaning":"feel (感覺)"},"suffix":{"text":"-itive","meaning":"tending to (傾向)"},"logic":"容易感受到的，即「敏感的」。"}', 'sensitive issue / sensitive skin; sensitive information / sensitive issue / price-sensitive', '[{"en":"She is very sensitive to criticism.","zh-TW":"她對批評很敏感。"},{"en":"This is a sensitive topic.","zh-TW":"這是一個敏感的話題。"},{"en":"This is sensitive information; do not share it.","zh-TW":"這是機密資訊，不要分享。"},{"en":"He is very sensitive to criticism.","zh-TW":"他對批評非常敏感。"}]', '{"noun":"sensitivity","verb":"sensitize","adjective":"sensitive, insensitive","adverb":"sensitively"}', NULL, 3, 5913, NULL),
(5914, 'sensitivity analysis', '/ˌsensɪˈtɪvɪti əˈnæləsɪs/', 'noun', '{"zh-TW":["敏感度分析"],"en":["analysis of how the variation in input variables affects an output"]}', NULL, 'conduct sensitivity analysis / sensitivity analysis results / key sensitivity analysis', '[{"en":"Sensitivity analysis shows how changes in assumptions affect valuations.","zh-TW":"敏感度分析顯示假設的變化如何影響估值。"},{"en":"The financial model includes a sensitivity analysis on interest rate changes.","zh-TW":"財務模型包括對利率變化的敏感度分析。"}]', NULL, NULL, 5, 5914, NULL),
(5915, 'sensor', '/ˈsɛnsər/', 'noun', '{"zh-TW":["感應器"],"en":["a device that detects changes in the environment"]}', NULL, 'motion sensor / temperature sensor', '[{"en":"The motion sensor turns on the light.","zh-TW":"動作感應器會開燈。"},{"en":"Modern cars have many sensors.","zh-TW":"現代汽車有很多感應器。"}]', NULL, NULL, 2, 5915, NULL),
(5916, 'sentiment', '/''sentɪmənt/', 'noun', '{"zh-TW":["情感；看法；輿論"],"en":["a view of or attitude toward a situation or event; an emotion or feeling"]}', NULL, 'public sentiment / positive sentiment / sentimental value', '[{"en":"Public sentiment shifted dramatically after the company''s controversial announcement.","zh-TW":"在公司發表有爭議的聲明後，公眾輿論發生了巨大變化。"},{"en":"The poem captured the sentiment of longing and hope felt by many immigrants.","zh-TW":"這首詩捕捉了許多移民所感受到的渴望和希望的情感。"}]', '{"adjective":"sentimental","adverb":"sentimentally","noun2":"sentimentality"}', NULL, 3, 5916, NULL),
(5917, 'SEO', '/ˌes iː ˈoʊ/', 'noun', '{"zh-TW":["搜尋引擎優化"],"en":["search engine optimization; improving a website''s visibility in search results"]}', NULL, 'SEO strategy / on-page SEO / SEO audit / improve SEO', '[{"en":"Investing in SEO doubled the website''s organic traffic.","zh-TW":"投資搜尋引擎優化使網站的自然流量翻倍。"},{"en":"Good SEO requires both technical and content expertise.","zh-TW":"良好的搜尋引擎優化需要技術和內容兩方面的專業知識。"}]', '{"full form":"search engine optimization","verb":"optimize"}', NULL, 1, 5917, NULL),
(5918, 'separate', '/ˈsepəreɪt/', 'verb, adjective', '{"zh-TW":["分開；區分","個別的；獨立的"],"en":["to divide or keep apart","forming a unit by itself"]}', NULL, 'separate from / separate issue / keep separate', '[{"en":"Please keep personal and business expenses separate.","zh-TW":"請將個人和商業支出分開。"},{"en":"The two departments operate as separate entities.","zh-TW":"這兩個部門作為獨立的實體運作。"}]', '{"noun":"separation","verb":"separate","adjective":"separate","adverb":"separately"}', NULL, 3, 5918, 453),
(5919, 'sequence', '/ˈsiːkwəns/', 'noun', '{"zh-TW":["順序；序列","一連串"],"en":["an order in which things follow","a series of related events"]}', NULL, 'in sequence / sequence of events / logical sequence', '[{"en":"The tasks must be completed in sequence.","zh-TW":"這些任務必須按順序完成。"},{"en":"A sequence of errors led to the failure.","zh-TW":"一連串的錯誤導致了失敗。"}]', '{"noun":"sequence","adjective":"sequential","adverb":"sequentially"}', NULL, 3, 5919, NULL),
(5920, 'sequestration', '/ˌsiːkwəˈstreɪʃən/', 'noun', '{"zh-TW":["扣押；隔離；碳封存"],"en":["the isolation of property or a jury; the removal of carbon dioxide from the atmosphere"]}', NULL, 'carbon sequestration / asset sequestration / jury sequestration', '[{"en":"Carbon sequestration in forests helps offset greenhouse gas emissions.","zh-TW":"森林中的碳封存有助於抵消溫室氣體排放。"},{"en":"Budget sequestration automatically cuts government spending across multiple departments.","zh-TW":"預算自動削減機制自動削減多個部門的政府支出。"}]', '{"verb":"sequester","adjective":"sequestered"}', NULL, 5, 5920, NULL),
(5921, 'serialization', '/ˌsɪəriəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["連載；系列化"],"en":["the publication of a work in installments"]}', NULL, 'book serialization / TV serialization / newspaper serialization', '[{"en":"The novel was first published through serialization in a literary magazine.","zh-TW":"這部小說最初通過在文學雜誌上連載出版。"},{"en":"Streaming platforms have revived serialization as a storytelling format.","zh-TW":"串流媒體平台使連載作為一種說故事的形式重新復活。"}]', '{"verb":"serialize","adjective":"serialized"}', NULL, 5, 5921, NULL),
(5922, 'series', '/ˈsɪriːz/', 'noun', '{"zh-TW":["系列；連續","一系列"],"en":["a number of similar things coming one after another"]}', NULL, 'a series of / series production / in series', '[{"en":"A series of meetings was held last week.","zh-TW":"上週舉行了一系列會議。"},{"en":"The company launched a new product series.","zh-TW":"公司推出了新的產品系列。"}]', '{"noun":"series","adjective":"serial"}', NULL, 2, 5922, NULL),
(5923, 'Series A', '/ˈsɪəriːz eɪ/', 'noun', '{"zh-TW":["A輪融資"],"en":["the first significant round of venture capital financing for a startup"]}', NULL, 'raise Series A / Series A investor / close a Series A round', '[{"en":"The startup raised $10 million in a Series A funding round.","zh-TW":"這家新創公司在A輪融資中籌集了1000萬美元。"},{"en":"After closing Series A, the team expanded to 50 employees.","zh-TW":"A輪融資完成後，團隊擴大到50名員工。"}]', '{"related":"seed funding, Series B"}', NULL, 3, 5923, NULL),
(5924, 'series funding', '/ˈsɪəriːz ˈfʌndɪŋ/', 'noun', '{"zh-TW":["系列融資"],"en":["staged investment rounds in a startup company"]}', NULL, 'close a Series A / Series B funding / Series C round', '[{"en":"The company completed a 50 million Series C funding round.","zh-TW":"公司完成了5000萬元的C輪融資。"},{"en":"Each series funding round typically values the company higher.","zh-TW":"每輪系列融資通常對公司的估值更高。"}]', NULL, NULL, 5, 5924, NULL),
(5925, 'serious', 'ˈsɪriəs', 'adjective', '{"zh-TW":["嚴肅的；嚴重的","認真的"],"en":["important and needing attention","not joking"]}', NULL, 'serious issue/serious mistake', '[{"en":"This is a serious quality issue.","zh-TW":"這是一個嚴重的品質問題。"}]', '{"noun":"seriousness","adverb":"seriously"}', NULL, 3, 5925, NULL),
(5926, 'serve', '/sɜːrv/', 'verb', '{"zh-TW":["服務；供應","擔任"],"en":["to provide a service","to fulfill a function"]}', NULL, 'serve customers / serve as / serve a purpose', '[{"en":"This room serves as both office and meeting space.","zh-TW":"這個房間既是辦公室也是會議空間。"},{"en":"We aim to serve our customers better.","zh-TW":"我們的目標是更好地服務客戶。"}]', '{"noun":"service, server","verb":"serve"}', NULL, 2, 5926, NULL),
(5927, 'server', '/ˈsɜːrvər/', 'noun', '{"zh-TW":["伺服器"],"en":["a computer that provides data to other computers"]}', NULL, 'web server / server room', '[{"en":"The server crashed last night.","zh-TW":"伺服器昨晚當機了。"},{"en":"Data is stored on the server.","zh-TW":"資料存儲在伺服器上。"}]', NULL, NULL, 2, 5927, NULL),
(5928, 'serverless', '/ˈsɜːrvərləs/', 'adjective', '{"zh-TW":["無伺服器的"],"en":["relating to a cloud model where the provider manages infrastructure dynamically"]}', NULL, 'serverless architecture / serverless function / serverless computing', '[{"en":"Serverless computing lets developers focus on code rather than infrastructure.","zh-TW":"無伺服器計算讓開發者專注於代碼而非基礎設施。"},{"en":"Serverless functions scale automatically in response to demand.","zh-TW":"無伺服器函數根據需求自動擴展。"}]', NULL, NULL, 4, 5928, NULL),
(5929, 'service', 'ˈsɜːrvɪs', 'noun', '{"zh-TW":["服務；業務","維修"],"en":["work done for customers","assistance provided"]}', NULL, 'customer service/after-sales service', '[{"en":"Our customer service team is available 24/7.","zh-TW":"我們的客戶服務團隊全天候提供服務。"}]', '{"verb":"service","adjective":"serviceable","adverb":"serviceably"}', NULL, 3, 5929, 215),
(5930, 'service agreement', '/ˈsɜːrvɪs əˈɡriːmənt/', 'noun', '{"zh-TW":["服務協議"],"en":["a contract outlining the terms of service between a provider and client"]}', NULL, 'sign a service agreement / service agreement terms', '[{"en":"The service agreement guarantees 24-hour response times.","zh-TW":"服務協議保證24小時響應時間。"},{"en":"Review the service agreement carefully before signing.","zh-TW":"在簽署前仔細審查服務協議。"}]', NULL, NULL, 5, 5930, NULL),
(5931, 'service contract', '/ˈsɜːrvɪs ˈkɒntrækt/', 'noun', '{"zh-TW":["服務合約"],"en":["a legal agreement for the ongoing provision of services"]}', NULL, 'sign a service contract / renew a service contract', '[{"en":"The service contract covers maintenance for three years.","zh-TW":"服務合約涵蓋三年的維護服務。"},{"en":"A service contract was signed before the system went live.","zh-TW":"在系統上線前簽署了服務合約。"}]', NULL, NULL, 5, 5931, NULL),
(5932, 'service delivery', '/ˈsɜːrvɪs dɪˈlɪvəri/', 'noun', '{"zh-TW":["服務交付"],"en":["the process of providing a service to customers according to agreed standards"]}', NULL, 'improve service delivery / service delivery model', '[{"en":"The company redesigned its service delivery process to reduce wait times.","zh-TW":"公司重新設計了服務交付流程以減少等待時間。"},{"en":"Service delivery failures increase customer complaints and churn.","zh-TW":"服務交付失敗增加了客戶投訴和流失。"}]', NULL, NULL, 5, 5932, NULL),
(5933, 'service level', '/ˈsɜːrvɪs ˈlevəl/', 'noun', '{"zh-TW":["服務水平"],"en":["a measurable standard defining the performance expected in service delivery"]}', NULL, 'maintain service levels / service level target', '[{"en":"The team consistently met all service level targets for the quarter.","zh-TW":"團隊在整個季度中持續達到了所有服務水平目標。"},{"en":"Customers who experience low service levels are more likely to churn.","zh-TW":"遭遇低服務水平的客戶更有可能流失。"}]', NULL, NULL, 5, 5933, NULL),
(5934, 'service level agreement', '/ˈsɜːrvɪs ˈlɛvəl əˈɡriːmənt/', 'noun', '{"zh-TW":["服務水準協議"],"en":["a contract defining the expected level of service"]}', NULL, 'sign a service level agreement / meet SLA requirements', '[{"en":"The service level agreement guarantees 99% uptime.","zh-TW":"服務水準協議保證99%的正常運行時間。"},{"en":"Failure to meet the SLA results in financial penalties.","zh-TW":"未能達到服務水準協議將導致財務處罰。"}]', '{"abbreviation":"SLA"}', NULL, 5, 5934, NULL),
(5935, 'service recovery', '/ˈsɜːrvɪs rɪˈkʌvəri/', 'noun', '{"zh-TW":["服務補救"],"en":["the process of resolving a service failure to restore customer satisfaction"]}', NULL, 'service recovery strategy / effective service recovery', '[{"en":"Swift service recovery turned the unhappy customer into a loyal advocate.","zh-TW":"迅速的服務補救將不滿意的客戶轉變為忠實的擁護者。"},{"en":"Service recovery training helps frontline staff handle complaints.","zh-TW":"服務補救培訓幫助前線員工處理投訴。"}]', NULL, NULL, 5, 5935, NULL),
(5936, 'session', '/ˈseʃn/', 'noun', '{"zh-TW":["會議；會期","一段時間"],"en":["a period of time for an activity","a formal meeting"]}', NULL, 'training session / in session / brainstorming session', '[{"en":"The training session lasted two hours.","zh-TW":"培訓課程持續了兩個小時。"},{"en":"Court is now in session.","zh-TW":"法庭現在開庭。"}]', '{"noun":"session"}', NULL, 3, 5936, NULL),
(5937, 'set', '/sɛt/', 'verb', '{"zh-TW":["設定；放置；一套"],"en":["to put in position","to fix or decide","a group of items"]}', NULL, 'set up / set a goal', '[{"en":"We set ambitious goals for this year.","zh-TW":"我們為今年設定了雄心壯志的目標。"},{"en":"Let me help you set up the system.","zh-TW":"讓我幫你設定系統。"}]', '{"verb":"set","noun":"set","noun2":"setting","noun3":"setup"}', NULL, 1, 5937, NULL),
(5938, 'set menu', '/sɛt ˈmɛnjuː/', 'noun', '{"zh-TW":["套餐；固定菜單"],"en":["a menu with a fixed selection of courses at one price"]}', NULL, 'order the set menu / set menu options', '[{"en":"The set menu at lunch is a great value.","zh-TW":"午餐套餐非常划算。"},{"en":"We chose the three-course set menu for dinner.","zh-TW":"我們選擇了三道菜的晚餐套餐。"}]', NULL, NULL, 3, 5938, NULL),
(5939, 'setback', '/''setbæk/', 'noun', '{"zh-TW":["挫折；退步；阻礙"],"en":["a reversal or check in progress; an unexpected problem that slows or prevents progress"]}', NULL, 'face a setback / overcome a setback / temporary setback', '[{"en":"She viewed each setback as an opportunity to learn and grow stronger.","zh-TW":"她將每次挫折視為學習和成長的機會。"},{"en":"The project suffered a significant setback when the main contractor withdrew.","zh-TW":"當主要承包商退出時，項目遭受了重大挫折。"}]', '{"verb":"set back","adjective":"set back"}', NULL, 3, 5939, NULL),
(5940, 'settle', '/ˈsetl/', 'verb', '{"zh-TW":["解決；安頓","定居；結算"],"en":["to resolve a dispute","to pay a debt or establish in a place"]}', NULL, 'settle a dispute / settle down / settle an account', '[{"en":"They settled the dispute out of court.","zh-TW":"他們在庭外解決了糾紛。"},{"en":"Please settle the account by Friday.","zh-TW":"請在週五前結清帳款。"}]', '{"noun":"settlement","verb":"settle"}', NULL, 2, 5940, NULL),
(5941, 'settlement', '/ˈsɛtəlmənt/', 'noun', '{"zh-TW":["和解；結案"],"en":["an agreement resolving a dispute"]}', NULL, 'reach a settlement / out-of-court settlement', '[{"en":"The two companies reached a settlement out of court.","zh-TW":"兩家公司在法庭外達成和解。"},{"en":"The settlement amount was kept confidential.","zh-TW":"和解金額保密。"}]', '{"verb":"settle","adjective":"settled"}', NULL, 4, 5941, NULL),
(5942, 'settlement date', '/ˈsɛtəlmənt deɪt/', 'noun', '{"zh-TW":["結算日；清算日"],"en":["the date on which a financial transaction is finalized"]}', NULL, 'confirm the settlement date / settlement date approaching', '[{"en":"The settlement date for the property purchase is June 30th.","zh-TW":"房產購買的結算日為6月30日。"},{"en":"Funds must be available on the settlement date.","zh-TW":"資金必須在結算日準備好。"}]', NULL, NULL, 5, 5942, NULL),
(5943, 'severance', '/ˈsevərəns/', 'noun', '{"zh-TW":["遣散；解雇","遣散費"],"en":["the ending of a connection; compensation for job loss"]}', NULL, 'severance package / severance pay / severance agreement', '[{"en":"Laid-off workers received a generous severance package.","zh-TW":"被解僱的工人獲得了優厚的遣散方案。"},{"en":"The severance agreement included six months'' pay.","zh-TW":"遣散協議包含六個月的薪水。"}]', '{"noun":"severance","verb":"sever"}', NULL, 3, 5943, NULL),
(5944, 'severance pay', '/ˈsɛvərəns peɪ/', 'noun', '{"zh-TW":["遣散費；資遣費"],"en":["compensation paid to an employee upon termination"]}', NULL, 'receive severance pay / severance pay package', '[{"en":"She received two months of severance pay when laid off.","zh-TW":"她被裁員時收到了兩個月的遣散費。"},{"en":"The severance pay package included unused vacation days.","zh-TW":"遣散費方案包含未使用的假期天數。"}]', NULL, NULL, 5, 5944, NULL),
(5945, 'severe', '/sɪˈvɪr/', 'adjective', '{"zh-TW":["嚴重的；嚴厲的"],"en":["very serious or harsh"]}', NULL, 'severe consequences / severe weather / severe shortage', '[{"en":"The region is facing a severe water shortage.","zh-TW":"該地區正面臨嚴重的水資源短缺。"},{"en":"Severe penalties apply for violations.","zh-TW":"違規將受到嚴厲處罰。"}]', '{"noun":"severity","adjective":"severe","adverb":"severely"}', NULL, 2, 5945, NULL),
(5946, 'shadow banking', '/ˈʃædəʊ ˈbæŋkɪŋ/', 'noun', '{"zh-TW":["影子銀行"],"en":["financial intermediaries that provide bank-like services but are not subject to standard banking regulation"]}', NULL, 'regulate shadow banking / shadow banking sector / shadow banking risk', '[{"en":"Shadow banking entities include hedge funds and money market funds that operate outside traditional oversight.","zh-TW":"影子銀行實體包括在傳統監管之外運作的對沖基金和貨幣市場基金。"},{"en":"The growth of shadow banking creates systemic risks that regulators struggle to monitor.","zh-TW":"影子銀行的增長製造了監管機構難以監控的系統性風險。"}]', NULL, NULL, 5, 5946, NULL),
(5947, 'shape', '/ʃeɪp/', 'noun', '{"zh-TW":["形狀；狀態"],"en":["the form of something","condition"]}', NULL, 'in good shape / take shape', '[{"en":"The plan is taking shape.","zh-TW":"計畫正在成形。"},{"en":"The company is in good shape financially.","zh-TW":"公司財務狀況良好。"}]', '{"noun":"shape","verb":"shape","adjective":"shaped"}', NULL, 2, 5947, NULL),
(5948, 'share', '/ʃer/', 'noun, verb', '{"zh-TW":["股份；份額","分享；共用"],"en":["a portion of something","to give part of something to others"]}', NULL, 'market share / share information / share price', '[{"en":"The company''s market share increased by 5%.","zh-TW":"公司的市場佔有率增加了5%。"},{"en":"Please share the report with the team.","zh-TW":"請與團隊分享這份報告。"}]', '{"noun":"share, shareholder","verb":"share"}', NULL, 2, 5948, NULL),
(5949, 'share buyback', '/ʃeər ˈbaɪbæk/', 'noun', '{"zh-TW":["股份回購"],"en":["when a company repurchases its own shares from the market"]}', NULL, 'announce a share buyback / fund a share buyback', '[{"en":"The board authorized a 50 million dollar share buyback program.","zh-TW":"董事會授權了5000萬美元的股份回購計劃。"},{"en":"A share buyback reduces the number of outstanding shares.","zh-TW":"股份回購減少了流通股數量。"}]', NULL, NULL, 5, 5949, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5950, 'share capital', '/ʃeər ˈkæpɪtl/', 'noun', '{"zh-TW":["股本；股份資本"],"en":["the amount of money raised by issuing shares in a company"]}', NULL, 'increase share capital / share capital structure', '[{"en":"The company raised its share capital through a rights issue.","zh-TW":"公司通過配股增加了股本。"},{"en":"Share capital represents the owners investment in the business.","zh-TW":"股本代表了業主對企業的投資。"}]', NULL, NULL, 5, 5950, NULL),
(5951, 'shared accommodation', '/''ʃeərd əˌkɒməˌdeɪʃən/', 'noun', '{"zh-TW":["合租住宿；共享住房"],"en":["accommodation shared by two or more people who are not family members"]}', NULL, 'find shared accommodation / live in shared accommodation / shared accommodation costs', '[{"en":"Many young professionals in expensive cities opt for shared accommodation.","zh-TW":"許多在昂貴城市的年輕專業人士選擇合租住宿。"},{"en":"Shared accommodation significantly reduces living costs for students.","zh-TW":"合租住宿顯著降低了學生的生活費用。"}]', NULL, NULL, 5, 5951, NULL),
(5952, 'shareholder', '/ˈʃerhoʊldər/', 'noun', '{"zh-TW":["股東"],"en":["an owner of shares in a company"]}', NULL, 'major shareholder / shareholder meeting / shareholder value', '[{"en":"Shareholders approved the merger at the meeting.","zh-TW":"股東在會議上批准了合併案。"},{"en":"The company focuses on increasing shareholder value.","zh-TW":"公司專注於提升股東價值。"}]', '{"noun":"shareholder, shareholding"}', NULL, 4, 5952, NULL),
(5953, 'shareholder activism', '/ˈʃeəhəʊldər ˈæktɪvɪzəm/', 'noun', '{"zh-TW":["股東積極主義"],"en":["active involvement by shareholders to pressure companies on strategy and governance"]}', NULL, 'engage in shareholder activism / rise of shareholder activism / shareholder activism campaign', '[{"en":"Shareholder activism has pushed many companies to improve sustainability practices.","zh-TW":"股東積極主義推動了許多公司改善永續性實踐。"},{"en":"Activist investors use their stakes to demand board changes and strategic shifts.","zh-TW":"積極投資者利用其持股要求董事會變更和戰略轉變。"}]', NULL, NULL, 5, 5953, NULL),
(5954, 'shareholder agreement', '/ˈʃeərholdər əˈɡriːmənt/', 'noun', '{"zh-TW":["股東協議"],"en":["a contract between shareholders governing ownership rights and responsibilities"]}', NULL, 'draft a shareholder agreement / shareholder agreement terms', '[{"en":"The shareholder agreement outlines voting rights and dividend policies.","zh-TW":"股東協議概述了投票權和股息政策。"},{"en":"Disputes between shareholders are governed by the shareholder agreement.","zh-TW":"股東之間的糾紛由股東協議管轄。"}]', NULL, NULL, 5, 5954, NULL),
(5955, 'shareholder equity', '/ˈʃeəhoʊldər ˈekwɪti/', 'noun', '{"zh-TW":["股東權益"],"en":["the residual interest in assets after deducting liabilities from a company''s balance sheet"]}', NULL, 'calculate shareholder equity / increase shareholder equity', '[{"en":"Retained earnings are the main driver of growing shareholder equity.","zh-TW":"留存收益是股東權益增長的主要驅動力。"},{"en":"Shareholder equity declined after the share buyback reduced reserves.","zh-TW":"在股票回購減少了儲備後，股東權益下降了。"}]', NULL, NULL, 5, 5955, NULL),
(5956, 'shareholder meeting', '/ˈʃeərhoʊldər ˈmiːtɪŋ/', 'noun', '{"zh-TW":["股東大會"],"en":["a formal meeting where shareholders vote on company matters"]}', NULL, 'hold a shareholder meeting / attend the shareholder meeting', '[{"en":"The annual shareholder meeting approved the dividend payment.","zh-TW":"年度股東大會批准了股息支付。"},{"en":"Proxy votes were submitted before the shareholder meeting.","zh-TW":"委託投票在股東大會前提交了。"}]', '{"abbreviation":"AGM for annual"}', NULL, 5, 5956, NULL),
(5957, 'shareholder return', '/ˈʃeərholdər rɪˈtɜːrn/', 'noun', '{"zh-TW":["股東回報"],"en":["the total gain a shareholder receives from owning shares, including dividends and capital gains"]}', NULL, 'maximize shareholder return / shareholder return analysis', '[{"en":"The board''s primary goal is to maximize shareholder return.","zh-TW":"董事會的主要目標是最大化股東回報。"},{"en":"Dividends and capital gains both contribute to shareholder return.","zh-TW":"股息和資本收益都有助於股東回報。"}]', NULL, NULL, 5, 5957, NULL),
(5958, 'shareholder value', '/ˈʃeərhoʊldər ˈvæljuː/', 'noun', '{"zh-TW":["股東價值"],"en":["the value delivered to shareholders through dividends and share price growth"]}', NULL, 'create shareholder value / maximize shareholder value', '[{"en":"The merger was justified by its potential to create shareholder value.","zh-TW":"合併的理由是其創造股東價值的潛力。"},{"en":"Critics argued the restructuring destroyed shareholder value.","zh-TW":"批評者認為重組破壞了股東價值。"}]', NULL, NULL, 5, 5958, NULL),
(5959, 'shareholders equity', '/ˈʃeərhoʊldərz ˈekwɪti/', 'noun', '{"zh-TW":["股東權益"],"en":["the residual interest in company assets after deducting liabilities"]}', NULL, 'calculate shareholders equity / increase shareholders equity', '[{"en":"Shareholders equity grew as retained earnings accumulated over the years.","zh-TW":"隨著保留盈餘多年累積，股東權益增長了。"},{"en":"A negative shareholders equity indicates a company owes more than it owns.","zh-TW":"負股東權益表明公司負債超過資產。"}]', NULL, NULL, 5, 5959, NULL),
(5960, 'sharp', '/ʃɑːrp/', 'adverb, adjective, noun', '{"zh-TW":["【主要意義-形容詞】鋒利的；尖銳的","【次要意義-副詞】準時地；整點（時間）","【次要意義-形容詞】聰明的；機靈的","【次要意義-形容詞】突然的；急劇的"],"en":["[primary - adjective] having a fine cutting edge or point","[secondary - adverb] exactly at the stated time","[secondary - adjective] intelligent and quick to learn","[secondary - adjective] sudden and intense"]}', NULL, 'at 9 o''clock sharp / sharp decline / sharp contrast / a sharp eye', '[{"en":"The meeting begins at 8 o clock sharp; latecomers will not be admitted.","zh-TW":"會議於8點整開始，遲到者不予入場。"},{"en":"There was a sharp decline in sales during the fourth quarter.","zh-TW":"第四季度的銷售額出現了急劇下降。"},{"en":"She has a sharp eye for detail that makes her an excellent proofreader.","zh-TW":"她對細節的敏銳眼光使她成為一名出色的校對員。"}]', '{"adverb":"sharply","noun":"sharpness"}', 'sharp 作副詞表「準時地/整點」（at 9 sharp），是 TOEIC 會議通知常見用法；sharp decline/increase 表「急劇的下降/上升」，也是財務報告高頻搭配。', 2, 5960, NULL),
(5961, 'shelf', '/ʃelf/', 'noun', '{"zh-TW":["架子；擱板"],"en":["a flat piece of wood or metal fixed to a wall for holding things"]}', '{"root":{"text":"shelf","meaning":"ledge (突出物)"},"logic":"固定在牆上的平面，用來放置物品。"}', 'shelf life / top shelf / off the shelf', '[{"en":"Put the books back on the shelf.","zh-TW":"把書放回書架上。"},{"en":"This product has a shelf life of two years.","zh-TW":"這個產品的保質期是兩年。"}]', '{"noun_plural":"shelves"}', NULL, 2, 5961, NULL),
(5962, 'shelf life', '/ʃɛlf laɪf/', 'noun', '{"zh-TW":["保存期限；貨架壽命"],"en":["the length of time a product can be stored before it becomes unusable"]}', NULL, 'check the shelf life / short shelf life', '[{"en":"Always check the shelf life of perishable products.","zh-TW":"務必檢查易腐商品的保存期限。"},{"en":"Fresh produce has a shorter shelf life than canned goods.","zh-TW":"新鮮農產品的保存期限比罐頭食品短。"}]', NULL, NULL, 4, 5962, NULL),
(5963, 'shelter', '/ˈʃeltər/', 'noun, verb', '{"zh-TW":["庇護所；避難所","庇護；保護"],"en":["a place giving protection","to provide protection"]}', NULL, 'tax shelter / take shelter / emergency shelter', '[{"en":"The building served as an emergency shelter.","zh-TW":"這棟建築用作緊急避難所。"},{"en":"The policy shelters small businesses from heavy taxes.","zh-TW":"該政策保護小型企業免受重稅。"}]', '{"noun":"shelter","verb":"shelter"}', NULL, 3, 5963, NULL),
(5964, 'shift', '/ʃɪft/', 'noun, verb', '{"zh-TW":["轉變；輪班","轉移；移動"],"en":["a change in position or direction","to move from one place to another"]}', NULL, 'shift in demand / night shift / shift focus', '[{"en":"There has been a shift in consumer preferences.","zh-TW":"消費者偏好出現了轉變。"},{"en":"She works the night shift at the factory.","zh-TW":"她在工廠值夜班。"}]', '{"noun":"shift","verb":"shift"}', NULL, 2, 5964, NULL),
(5965, 'ship', 'ʃɪp', 'verb', '{"zh-TW":["運送；出貨","裝運"],"en":["to send goods by transport","to dispatch"]}', NULL, 'ship an order/ship worldwide', '[{"en":"We ship orders within 24 hours.","zh-TW":"我們在24小時內出貨。"}]', '{"noun":"shipment, shipping","adjective":"shipped"}', NULL, 1, 5965, NULL),
(5966, 'shipment', '/ˈʃɪpmənt/', 'noun', '{"zh-TW":["貨運；一批貨物"],"en":["a quantity of goods sent or transported together"]}', NULL, 'track a shipment / shipment status', '[{"en":"The shipment arrived three days ahead of schedule.","zh-TW":"這批貨物提前三天抵達。"},{"en":"You can track your shipment online with the tracking number.","zh-TW":"您可以使用追蹤號碼在線追蹤您的貨運。"}]', '{"verb":"ship","noun":"shipper","adjective":"shipped"}', NULL, 3, 5966, 454),
(5967, 'shipper', '/''ʃɪpər/', 'noun', '{"zh-TW":["託運人；發貨方"],"en":["a person or company that ships goods"]}', NULL, 'reputable shipper / shipper documentation / shipper of record', '[{"en":"The shipper must provide accurate documentation for all international goods.","zh-TW":"託運人必須為所有國際貨物提供準確的文件。"},{"en":"She worked as a shipper, coordinating outbound shipments for a large retailer.","zh-TW":"她擔任託運人，協調一家大型零售商的出境貨物。"}]', NULL, NULL, 3, 5967, NULL),
(5968, 'shipper of record', '/''ʃɪpər əv ˈrekərd/', 'noun', '{"zh-TW":["記錄上的托運人；正式托運方"],"en":["the party identified as the sender on shipping documentation and legally responsible for the shipment"]}', NULL, 'become the shipper of record / shipper of record requirements', '[{"en":"As the shipper of record, the company was responsible for all export compliance.","zh-TW":"作為記錄上的托運人，公司負責所有出口合規事宜。"},{"en":"E-commerce companies often act as the shipper of record for customer orders.","zh-TW":"電子商務公司通常作為客戶訂單的記錄上的托運人。"}]', NULL, NULL, 5, 5968, NULL),
(5969, 'shipping', '/ˈʃɪpɪŋ/', 'noun', '{"zh-TW":["運輸；航運"],"en":["the process of transporting goods from one place to another"]}', NULL, 'shipping cost / free shipping / shipping address / shipping carrier', '[{"en":"Offering free shipping increased online conversion rates.","zh-TW":"提供免費運輸提高了線上轉換率。"},{"en":"Shipping costs rose due to fuel price increases.","zh-TW":"由於燃料價格上漲，運輸成本增加了。"}]', '{"verb":"ship","noun":"shipper"}', NULL, 3, 5969, NULL),
(5970, 'shipping container', '/''ʃɪpɪŋ kənˌteɪnər/', 'noun', '{"zh-TW":["貨運集裝箱；貨櫃"],"en":["a standardized metal box used for transporting goods by sea, road, or rail"]}', NULL, 'pack a shipping container / full container load / shipping container dimensions', '[{"en":"The company loaded a full shipping container with electronic goods for export.","zh-TW":"公司裝滿了一個貨運集裝箱，裡面裝有出口的電子產品。"},{"en":"Shipping container prices surged as global demand outpaced supply.","zh-TW":"隨著全球需求超過供應，貨運集裝箱價格飆升。"}]', NULL, NULL, 5, 5970, NULL),
(5971, 'shipping manifest', '/ˈʃɪpɪŋ ˈmænɪfest/', 'noun', '{"zh-TW":["裝貨清單；運輸艙單"],"en":["a document listing all cargo aboard a ship or aircraft"]}', NULL, 'prepare a shipping manifest / review the shipping manifest', '[{"en":"The shipping manifest must be submitted to customs before departure.","zh-TW":"裝貨清單必須在出發前提交給海關。"},{"en":"Discrepancies between the shipping manifest and actual cargo can delay clearance.","zh-TW":"裝貨清單與實際貨物之間的差異可能延遲清關。"}]', NULL, NULL, 5, 5971, NULL),
(5972, 'shopping cart', '/ˈʃɒpɪŋ kɑːrt/', 'noun', '{"zh-TW":["購物車"],"en":["a container used to hold goods while shopping"]}', NULL, 'add to shopping cart / virtual shopping cart', '[{"en":"Add items to your shopping cart and proceed to checkout.","zh-TW":"將商品添加到購物車並繼續結帳。"},{"en":"She abandoned her shopping cart after seeing the shipping fee.","zh-TW":"她在看到運費後放棄了購物車。"}]', NULL, NULL, 5, 5972, NULL),
(5973, 'short', '/ʃɔːrt/', 'adjective', '{"zh-TW":["短的；不足的"],"en":["not long in length or time","insufficient"]}', NULL, 'in short / short-term', '[{"en":"In short, we need more funding.","zh-TW":"簡而言之，我們需要更多資金。"},{"en":"This is only a short-term solution.","zh-TW":"這只是短期的解決方案。"}]', '{"adjective":"short","noun":"shortage","verb":"shorten","adverb":"shortly"}', NULL, 2, 5973, NULL),
(5974, 'short position', '/ʃɔːrt pəˈzɪʃən/', 'noun', '{"zh-TW":["空頭部位；做空倉位"],"en":["selling a borrowed asset with the expectation its price will fall"]}', NULL, 'take a short position / cover a short position', '[{"en":"The fund took a short position in the overvalued stock.","zh-TW":"基金對被高估的股票持有空頭部位。"},{"en":"Short positions expose traders to unlimited losses if prices rise.","zh-TW":"如果價格上漲，空頭部位使交易者面臨無限損失。"}]', '{"opposite":"long position"}', NULL, 5, 5974, NULL),
(5975, 'short selling', '/ʃɔːrt ˈselɪŋ/', 'noun', '{"zh-TW":["賣空；放空"],"en":["selling borrowed securities hoping to buy them back at a lower price"]}', NULL, 'engage in short selling / short selling risk', '[{"en":"Short selling can be profitable when a stock''s price falls.","zh-TW":"當股票價格下跌時，賣空可以帶來利潤。"},{"en":"Regulators banned short selling during the market crisis.","zh-TW":"監管機構在市場危機期間禁止了賣空。"}]', '{"verb":"short sell"}', NULL, 5, 5975, NULL),
(5976, 'short-haul', '/ʃɔːrt hɔːl/', 'adjective', '{"zh-TW":["短途的"],"en":["involving a relatively short journey"]}', NULL, 'short-haul flight / short-haul route', '[{"en":"Short-haul flights are usually less than three hours.","zh-TW":"短途飛行通常不超過三小時。"},{"en":"Budget airlines dominate the short-haul market.","zh-TW":"廉價航空主導著短途市場。"}]', NULL, NULL, 4, 5976, NULL),
(5977, 'short-selling', '/ˌʃɔːrt ˈselɪŋ/', 'noun', '{"zh-TW":["放空；賣空"],"en":["selling borrowed securities with the intention of buying them back at a lower price"]}', NULL, 'engage in short-selling / short-selling strategy / ban short-selling', '[{"en":"Short-selling allows investors to profit from declining prices.","zh-TW":"放空允許投資者從下跌的價格中獲利。"},{"en":"Regulators sometimes restrict short-selling during market crises.","zh-TW":"監管機構有時在市場危機期間限制賣空。"}]', '{"verb":"short-sell","noun":"short-seller"}', NULL, 5, 5977, NULL),
(5978, 'short-term debt', '/ʃɔːrt tɜːrm det/', 'noun', '{"zh-TW":["短期債務"],"en":["borrowings due for repayment within one year"]}', NULL, 'manage short-term debt / reduce short-term debt', '[{"en":"The company refinanced its short-term debt to reduce liquidity pressure.","zh-TW":"公司對短期債務進行了再融資以降低流動性壓力。"},{"en":"Short-term debt is listed as a current liability on the balance sheet.","zh-TW":"短期債務在資產負債表上列為流動負債。"}]', NULL, NULL, 5, 5978, NULL),
(5979, 'short-term financing', '/ˌʃɔːrtˌtɜːrm ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["短期融資"],"en":["funding with a repayment period of one year or less"]}', NULL, 'use short-term financing / short-term financing options', '[{"en":"The company used short-term financing to cover its seasonal cash needs.","zh-TW":"公司使用短期融資來滿足其季節性現金需求。"},{"en":"Short-term financing is more flexible but typically carries higher interest.","zh-TW":"短期融資更靈活，但通常利率較高。"}]', '{"opposite":"long-term financing"}', NULL, 5, 5979, NULL),
(5980, 'short-term goal', '/ʃɔːrt tɜːrm ɡəʊl/', 'noun', '{"zh-TW":["短期目標"],"en":["an objective to be achieved in the near future"]}', NULL, 'set short-term goals / achieve short-term goals', '[{"en":"Setting short-term goals helps maintain focus and momentum.","zh-TW":"設定短期目標有助於保持專注和動力。"},{"en":"Her short-term goal is to complete the certification this year.","zh-TW":"她的短期目標是今年完成認證。"}]', NULL, NULL, 5, 5980, NULL),
(5981, 'short-term investment', '/ʃɔːrt tɜːrm ɪnˈvestmənt/', 'noun', '{"zh-TW":["短期投資"],"en":["an investment expected to be liquidated within one year"]}', NULL, 'make short-term investments / short-term investment portfolio', '[{"en":"The company held short-term investments in treasury bills.","zh-TW":"公司持有國庫券等短期投資。"},{"en":"Short-term investments are classified as current assets.","zh-TW":"短期投資歸類為流動資產。"}]', NULL, NULL, 5, 5981, NULL),
(5982, 'short-term liability', '/ˌʃɔːrtˌtɜːrm laɪˈæbɪlɪti/', 'noun', '{"zh-TW":["短期負債"],"en":["a financial obligation due within one year"]}', NULL, 'record a short-term liability / short-term liability management', '[{"en":"Accounts payable is classified as a short-term liability.","zh-TW":"應付帳款被歸類為短期負債。"},{"en":"The company must manage short-term liabilities carefully.","zh-TW":"公司必須謹慎管理短期負債。"}]', '{"opposite":"long-term liability"}', NULL, 5, 5982, NULL),
(5983, 'shortage', '/ˈʃɔːrtɪdʒ/', 'noun', '{"zh-TW":["短缺；不足"],"en":["a state of not having enough"]}', NULL, 'labor shortage / housing shortage / shortage of supplies', '[{"en":"The industry is experiencing a labor shortage.","zh-TW":"該行業正經歷勞動力短缺。"},{"en":"A shortage of raw materials delayed production.","zh-TW":"原物料短缺延遲了生產。"}]', '{"noun":"shortage","adjective":"short"}', NULL, 3, 5983, 455),
(5984, 'shortcoming', '/ˈʃɔːrtkʌmɪŋ/', 'noun', '{"zh-TW":["缺點；不足之處"],"en":["a fault or failure to meet a standard"]}', NULL, 'address shortcomings / identify shortcomings / overcome shortcomings', '[{"en":"The audit identified several shortcomings in the process.","zh-TW":"審計發現了流程中的幾個不足之處。"},{"en":"We must address these shortcomings before launch.","zh-TW":"我們必須在上線前解決這些缺點。"}]', '{"noun":"shortcoming"}', NULL, 4, 5984, NULL),
(5985, 'shortlist', '/ˈʃɔːrtlɪst/', 'noun', '{"zh-TW":["入圍名單；候選短名單"],"en":["a list of selected candidates for final consideration"]}', NULL, 'make the shortlist / draw up a shortlist / shortlist candidates', '[{"en":"Three firms made the shortlist for the contract.","zh-TW":"三家公司進入了合約的入圍名單。"},{"en":"Shortlisted candidates will be notified by Friday.","zh-TW":"入圍候選人將於週五前收到通知。"}]', '{"verb":"shortlist"}', NULL, 3, 5985, NULL),
(5986, 'show', '/ʃoʊ/', 'verb', '{"zh-TW":["展示；顯示"],"en":["to make visible","to demonstrate"]}', NULL, 'show up / trade show', '[{"en":"The data shows a clear trend.","zh-TW":"數據顯示了明確的趨勢。"},{"en":"We will attend the trade show next month.","zh-TW":"我們下個月會參加展覽會。"}]', '{"verb":"show","noun":"show","noun2":"showroom"}', NULL, 1, 5986, NULL),
(5987, 'showcase', '/ˈʃoʊkeɪs/', 'noun, verb', '{"zh-TW":["展示；陳列","展示"],"en":["a display or exhibition","to exhibit or present"]}', NULL, 'showcase products / showcase talent / showcase innovation', '[{"en":"The event showcases the latest industry innovations.","zh-TW":"活動展示了最新的產業創新。"},{"en":"We need a platform to showcase our work.","zh-TW":"我們需要一個平台來展示我們的工作。"}]', '{"noun":"showcase","verb":"showcase"}', NULL, 3, 5987, NULL),
(5988, 'shower', '/ˈʃaʊər/', 'noun', '{"zh-TW":["陣雨；淋浴"],"en":["a brief fall of rain","a device for washing the body"]}', '{"root":{"text":"shower","meaning":"brief rain (短雨)"},"logic":"指短暫的降雨或用水沖洗。"}', 'rain shower / take a shower / scattered showers', '[{"en":"Scattered showers are expected this afternoon.","zh-TW":"今天下午預計會有零星陣雨。"},{"en":"I take a shower every morning.","zh-TW":"我每天早上淋浴。"}]', '{"adjective":"showery"}', NULL, 2, 5988, NULL),
(5989, 'shrink', '/ʃrɪŋk/', 'verb', '{"zh-TW":["縮小；萎縮"],"en":["to become smaller in size or amount"]}', NULL, 'shrink in size / shrink the budget / profit margins shrink', '[{"en":"The economy shrank by 2% last quarter.","zh-TW":"上季度經濟萎縮了2%。"},{"en":"Rising costs have shrunk profit margins.","zh-TW":"成本上升壓縮了利潤率。"}]', '{"noun":"shrinkage","verb":"shrink"}', NULL, 2, 5989, NULL),
(5990, 'shrinkage', '/ˈʃrɪŋkɪdʒ/', 'noun', '{"zh-TW":["損耗；庫存損失"],"en":["the reduction in stock due to theft, damage, or recording errors"]}', NULL, 'reduce shrinkage / shrinkage rate / inventory shrinkage', '[{"en":"Tighter security measures reduced shrinkage by 30%.","zh-TW":"更嚴格的安全措施將損耗減少了30%。"},{"en":"Annual shrinkage costs the retail industry billions of dollars.","zh-TW":"年度損耗使零售業損失了數十億元。"}]', NULL, NULL, 3, 5990, NULL),
(5991, 'shuttle', '/ˈʃʌtəl/', 'noun', '{"zh-TW":["接駁車；班車"],"en":["a vehicle regularly traveling between two places"]}', NULL, 'airport shuttle / hotel shuttle', '[{"en":"Take the free shuttle from the airport to the hotel.","zh-TW":"搭乘機場到飯店的免費接駁車。"},{"en":"The shuttle runs every fifteen minutes.","zh-TW":"接駁車每十五分鐘一班。"}]', '{"verb":"shuttle"}', NULL, 3, 5991, NULL),
(5992, 'side', '/saɪd/', 'noun', '{"zh-TW":["邊；方面"],"en":["a position to the left or right","an aspect"]}', NULL, 'on the side / side effect', '[{"en":"She runs a business on the side.","zh-TW":"她兼營一項副業。"},{"en":"Consider both sides of the argument.","zh-TW":"考慮論點的兩面。"}]', '{"noun":"side","adjective":"side","noun2":"sidebar"}', NULL, 1, 5992, NULL),
(5993, 'sightseeing', '/ˈsaɪtsiːɪŋ/', 'noun', '{"zh-TW":["觀光；遊覽"],"en":["the activity of visiting famous places"]}', NULL, 'go sightseeing / sightseeing tour', '[{"en":"We spent the afternoon sightseeing in the old city.","zh-TW":"我們下午在舊城區觀光。"},{"en":"The sightseeing bus offers a hop-on hop-off service.","zh-TW":"觀光巴士提供隨上隨下服務。"}]', '{"verb":"sightsee","noun":"sightseer"}', NULL, 4, 5993, NULL),
(5994, 'sign', '/saɪn/', 'noun, verb', '{"zh-TW":["標誌；跡象","簽署；簽名"],"en":["an indication or symbol","to write one''s name on a document"]}', NULL, 'sign a contract / sign of progress / warning sign', '[{"en":"Both parties signed the agreement today.","zh-TW":"雙方今天簽署了協議。"},{"en":"There are signs of economic recovery.","zh-TW":"有經濟復甦的跡象。"}]', '{"noun":"sign, signature, signal","verb":"sign, signal"}', NULL, 1, 5994, NULL),
(5995, 'sign-off', '/ˈsaɪn ɒf/', 'noun', '{"zh-TW":["批准；最終確認"],"en":["formal approval or authorization of work or a decision"]}', NULL, 'get sign-off / require sign-off / sign-off process / management sign-off', '[{"en":"Designs require sign-off from the marketing director before printing.","zh-TW":"設計在印刷前需要行銷總監的批准。"},{"en":"The final deliverable received sign-off from all stakeholders.","zh-TW":"最終可交付成果獲得了所有利益相關者的確認。"}]', '{"verb":"sign off"}', NULL, 3, 5995, NULL),
(5996, 'signaling', '/ˈsɪɡnəlɪŋ/', 'noun', '{"zh-TW":["信號傳遞；信號作用"],"en":["actions taken to convey information to another party in a market with asymmetric information"]}', NULL, 'price signaling / market signaling / cost of signaling', '[{"en":"Educational credentials function as a signaling mechanism in labor markets.","zh-TW":"教育資歷在勞動力市場中充當信號傳遞機制。"},{"en":"Corporate dividend increases are a form of signaling that management expects continued profitability.","zh-TW":"企業股息增加是一種信號，表明管理層預期持續盈利。"}]', '{"verb":"signal","noun2":"signal"}', NULL, 3, 5996, NULL),
(5997, 'signaling theory', '/ˈsɪɡnəlɪŋ ˈθɪəri/', 'noun', '{"zh-TW":["信號理論"],"en":["the study of how one party credibly conveys information to another"]}', NULL, 'apply signaling theory / labor market signaling theory / signaling theory in finance', '[{"en":"Signaling theory explains why education may be used to signal ability to employers.","zh-TW":"信號理論解釋了為什麼教育可以用來向雇主表明能力。"},{"en":"Dividends serve as a signal of financial health in signaling theory.","zh-TW":"在信號理論中，股息作為財務健康的信號。"}]', NULL, NULL, 5, 5997, NULL),
(5998, 'signatory', '/ˈsɪɡnətɔːri/', 'noun', '{"zh-TW":["簽署人；簽字方"],"en":["a party that has signed an agreement or contract"]}', NULL, 'signatory to an agreement / co-signatory / all signatories', '[{"en":"All signatories must be present for the contract to be binding.","zh-TW":"所有簽署人必須在場，合約才具有約束力。"},{"en":"The company is a signatory to the international environmental accord.","zh-TW":"公司是國際環境協議的簽署方。"}]', '{"plural":"signatories"}', NULL, 3, 5998, NULL),
(5999, 'signature', 'ˈsɪɡnɪtʃər', 'noun', '{"zh-TW":["簽名；署名","特徵"],"en":["a person''s name written by hand","a distinctive mark"]}', NULL, 'digital signature/require a signature', '[{"en":"Please provide your signature to confirm.","zh-TW":"請提供您的簽名以確認。"}]', '{"verb":"sign","adjective":"signed"}', NULL, 3, 5999, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6000, 'signature block', '/ˈsɪɡnətʃər blɒk/', 'noun', '{"zh-TW":["簽名欄；署名區塊"],"en":["the section in a document or email where a signature appears"]}', NULL, 'complete the signature block / add to the signature block', '[{"en":"All contracts include a signature block for both parties.","zh-TW":"所有合約都包含雙方的簽名欄。"},{"en":"Please ensure your email signature block includes your direct number.","zh-TW":"請確保您的電子郵件署名區塊包含您的直線電話。"}]', NULL, NULL, 5, 6000, NULL),
(6001, 'signature dish', '/ˈsɪɡnɪtʃər dɪʃ/', 'noun', '{"zh-TW":["招牌菜；特色菜"],"en":["the most famous or distinctive dish of a restaurant"]}', NULL, 'try the signature dish / create a signature dish', '[{"en":"The restaurant''s signature dish is the Peking duck.","zh-TW":"這家餐廳的招牌菜是北京烤鴨。"},{"en":"Every great chef has their own signature dish.","zh-TW":"每位出色的廚師都有自己的招牌菜。"}]', NULL, NULL, 5, 6001, NULL),
(6002, 'significant', '/sɪɡˈnɪfɪkənt/', 'adjective', '{"zh-TW":["重要的；顯著的","重大的；顯著的"],"en":["large enough to be noticed or have an effect","large or important enough to have an effect"]}', '{"root":{"text":"sign","meaning":"mark (標記)"},"suffix":{"text":"-ificant","meaning":"making (造成)"},"logic":"造成明顯標記的，即「顯著的」。"}', 'significant improvement / significant difference / statistically significant; significant improvement / significant impact / statistically significant', '[{"en":"There has been a significant improvement in sales.","zh-TW":"銷售額有了顯著改善。"},{"en":"This is a significant achievement.","zh-TW":"這是一項重大成就。"},{"en":"There has been a significant increase in sales.","zh-TW":"銷售額有了顯著的增長。"},{"en":"The new policy made a significant impact.","zh-TW":"新政策產生了重大影響。"}]', '{"noun":"significance","adverb":"significantly","adjective":"significant, insignificant"}', NULL, 4, 6002, 216),
(6003, 'significant other', '/sɪɡˈnɪfɪkənt ˈʌðər/', 'noun', '{"zh-TW":["重大關係方"],"en":["a shareholder or entity with substantial influence over a company"]}', NULL, 'notify significant others / disclose significant others', '[{"en":"The company must notify all significant others before a major decision.","zh-TW":"公司在重大決策前必須通知所有重大關係方。"},{"en":"Significant others are required to disclose their holdings annually.","zh-TW":"重大關係方需要每年披露其持股情況。"}]', NULL, NULL, 5, 6003, NULL),
(6004, 'silent partner', '/ˈsaɪlənt ˈpɑːrtnər/', 'noun', '{"zh-TW":["隱名合夥人；沉默合夥人"],"en":["an investor who provides capital but does not participate in day-to-day management"]}', NULL, 'bring in a silent partner / silent partner arrangement', '[{"en":"A silent partner invested $500,000 but had no role in operations.","zh-TW":"隱名合夥人投資了50萬元，但沒有參與運營。"},{"en":"Silent partners share in profits and losses without management responsibilities.","zh-TW":"隱名合夥人在沒有管理責任的情況下分享利潤和損失。"}]', '{"synonym":"sleeping partner"}', NULL, 5, 6004, NULL),
(6005, 'similar', '/ˈsɪmɪlər/', 'adjective', '{"zh-TW":["相似的；類似的"],"en":["resembling without being identical"]}', NULL, 'similar to / similar results / in a similar way', '[{"en":"Our products are similar to theirs in quality.","zh-TW":"我們的產品在品質上與他們的相似。"},{"en":"We faced a similar problem last year.","zh-TW":"去年我們面臨了類似的問題。"}]', '{"noun":"similarity","adjective":"similar","adverb":"similarly"}', NULL, 3, 6005, NULL),
(6006, 'simmer', '/''sɪmər/', 'verb', '{"zh-TW":["慢煮；用小火燉"],"en":["to cook or be cooked gently just below boiling point"]}', NULL, 'simmer on low heat / simmer for an hour / let it simmer', '[{"en":"Let the soup simmer for thirty minutes to allow the flavors to develop.","zh-TW":"讓湯在小火上慢煮三十分鐘，使風味充分融合。"},{"en":"Reduce the sauce by simmering it over low heat for twenty minutes.","zh-TW":"將醬汁在小火上慢煮二十分鐘使其濃縮。"}]', NULL, NULL, 2, 6006, NULL),
(6007, 'simple', '/ˈsɪmpəl/', 'adjective', '{"zh-TW":["簡單的"],"en":["easy to understand or do"]}', NULL, 'keep it simple / simple solution', '[{"en":"Keep the design simple and clean.","zh-TW":"保持設計簡潔。"},{"en":"There is a simple solution to this.","zh-TW":"這有一個簡單的解決辦法。"}]', '{"adjective":"simple","adverb":"simply","verb":"simplify","noun":"simplicity"}', NULL, 2, 6007, NULL),
(6008, 'simplify', '/ˈsɪmplɪfaɪ/', 'verb', '{"zh-TW":["簡化"],"en":["to make something easier to understand or do"]}', '{"suffix":{"text":"-ify","meaning":"使..."}}', 'simplify the process / simplify procedures', '[{"en":"We simplified the application process.","zh-TW":"我們簡化了申請流程。"},{"en":"The new software simplifies data management.","zh-TW":"新軟體簡化了資料管理。"}]', '{"noun":"simplification, simplicity","verb":"simplify","adjective":"simple"}', NULL, 3, 6008, 720),
(6009, 'simulate', '/ˈsɪmjuleɪt/', 'verb', '{"zh-TW":["模擬；模仿"],"en":["to imitate or reproduce conditions"]}', NULL, 'simulate conditions / simulate a scenario', '[{"en":"The software can simulate real-world conditions.","zh-TW":"這個軟體可以模擬真實世界的條件。"},{"en":"They simulated an emergency drill.","zh-TW":"他們模擬了一次緊急演練。"}]', '{"noun":"simulation, simulator","verb":"simulate","adjective":"simulated"}', NULL, 3, 6009, NULL),
(6010, 'simulation', '/ˌsɪmjʊˈleɪʃən/', 'noun', '{"zh-TW":["模擬"],"en":["a model of a real-world process used for testing or training"]}', NULL, 'run a simulation / computer simulation / simulation model', '[{"en":"Engineers use simulation to test aircraft behavior before construction.","zh-TW":"工程師在建造之前使用模擬來測試飛機行為。"},{"en":"The financial risk simulation models thousands of possible scenarios.","zh-TW":"財務風險模擬對數千種可能的情景進行建模。"}]', '{"verb":"simulate","adjective":"simulated"}', NULL, 4, 6010, NULL),
(6011, 'simultaneous', '/ˌsaɪmlˈteɪniəs/', 'adjective', '{"zh-TW":["同時的；同步的"],"en":["occurring at the same time"]}', NULL, 'simultaneous translation / simultaneous events', '[{"en":"The event will have simultaneous translation.","zh-TW":"活動將提供同步翻譯。"},{"en":"Both teams made simultaneous announcements.","zh-TW":"兩個團隊同時發布了公告。"}]', '{"noun":"simultaneity","adjective":"simultaneous","adverb":"simultaneously"}', NULL, 4, 6011, NULL),
(6012, 'sincere', '/sɪnˈsɪr/', 'adjective', '{"zh-TW":["真誠的"],"en":["free from pretense; genuine"]}', '{"root":{"text":"sincer","meaning":"pure/clean (純淨)"},"logic":"源自拉丁語 sincerus（純淨的），指不虛偽的。"}', 'sincere apology / sincere gratitude', '[{"en":"She offered a sincere apology.","zh-TW":"她表達了真誠的歉意。"},{"en":"He is sincere in his desire to help.","zh-TW":"他真心想幫忙。"}]', '{"noun":"sincerity","adverb":"sincerely"}', NULL, 3, 6012, NULL),
(6013, 'single occupancy', '/ˈsɪŋɡəl ˌɒkjʊpənsi/', 'noun', '{"zh-TW":["單人入住"],"en":["a hotel rate for one person staying in a room"]}', NULL, 'single occupancy rate / single occupancy supplement', '[{"en":"The single occupancy rate includes all standard amenities.","zh-TW":"單人入住費率包含所有標準設施。"},{"en":"Solo travelers may pay a single occupancy supplement.","zh-TW":"單人旅行者可能需要支付單人入住附加費。"}]', NULL, NULL, 5, 6013, NULL),
(6014, 'single point of failure', '/ˈsɪŋɡəl pɔɪnt əv ˈfeɪljər/', 'noun', '{"zh-TW":["單點故障"],"en":["one component whose failure causes the entire system to fail"]}', NULL, 'eliminate single point of failure / identify single point of failure / redundancy avoids single point of failure', '[{"en":"A well-designed system must eliminate any single point of failure.","zh-TW":"設計良好的系統必須消除任何單點故障。"},{"en":"Load balancing removes the single point of failure from web servers.","zh-TW":"負載平衡消除了網路伺服器的單點故障。"}]', NULL, NULL, 5, 6014, NULL),
(6015, 'single-source supplier', '/ˈsɪŋɡəl sɔːrs səˈplaɪər/', 'noun', '{"zh-TW":["單一來源供應商"],"en":["when only one supplier is used for a particular component or material"]}', NULL, 'use a single-source supplier / risks of single-source supplier', '[{"en":"Relying on a single-source supplier creates vulnerability to disruption.","zh-TW":"依賴單一來源供應商造成了對干擾的脆弱性。"},{"en":"The company diversified after its single-source supplier shut down.","zh-TW":"其單一來源供應商倒閉後，公司進行了多元化。"}]', NULL, NULL, 5, 6015, NULL),
(6016, 'sinking fund', '/ˈsɪŋkɪŋ fʌnd/', 'noun', '{"zh-TW":["償債基金；減債基金"],"en":["a fund established by setting aside money over time to pay off a debt"]}', NULL, 'create a sinking fund / sinking fund contribution', '[{"en":"The company set up a sinking fund to retire its bond debt.","zh-TW":"公司設立了償債基金以償還債券債務。"},{"en":"A sinking fund reduces the risk of default at maturity.","zh-TW":"償債基金降低了到期時違約的風險。"}]', NULL, NULL, 4, 6016, NULL),
(6017, 'sit', '/sɪt/', 'verb', '{"zh-TW":["坐"],"en":["to rest in a seated position"]}', NULL, 'sit down / sit in on', '[{"en":"Please sit down and make yourself comfortable.","zh-TW":"請坐下來放輕鬆。"},{"en":"May I sit in on the meeting?","zh-TW":"我可以旁聽這個會議嗎？"}]', '{"verb":"sit","noun":"seat","noun2":"sitting"}', NULL, 1, 6017, NULL),
(6018, 'site', '/saɪt/', 'noun', '{"zh-TW":["地點；場所","網站"],"en":["a place where something is located","a website"]}', NULL, 'construction site / on-site / website', '[{"en":"The construction site will be inspected tomorrow.","zh-TW":"施工現場明天將接受檢查。"},{"en":"Please visit our website for more information.","zh-TW":"請訪問我們的網站了解更多資訊。"}]', '{"noun":"site"}', NULL, 1, 6018, NULL),
(6019, 'site inspection', '/saɪt ɪnˈspekʃən/', 'noun', '{"zh-TW":["現場檢查；工地視察"],"en":["a visit to a location to assess conditions, compliance, or progress"]}', NULL, 'conduct a site inspection / site inspection report', '[{"en":"A site inspection confirmed the construction met safety standards.","zh-TW":"現場檢查確認了建築符合安全標準。"},{"en":"The client requested a site inspection before signing the lease.","zh-TW":"客戶在簽署租約前要求進行現場檢查。"}]', NULL, NULL, 5, 6019, NULL),
(6020, 'site visit', '/saɪt ˈvɪzɪt/', 'noun', '{"zh-TW":["現場參觀；工地視察"],"en":["a visit to a location to inspect progress or conditions"]}', NULL, 'schedule a site visit / conduct a site visit', '[{"en":"The client requested a site visit to check construction progress.","zh-TW":"客戶要求進行現場參觀以查看施工進展。"},{"en":"A site visit revealed several issues that needed immediate attention.","zh-TW":"現場視察發現了幾個需要立即處理的問題。"}]', NULL, NULL, 4, 6020, NULL),
(6021, 'situate', '/ˈsɪtʃueɪt/', 'verb', '{"zh-TW":["使位於；使處於"],"en":["to put in a certain position or context"]}', NULL, 'situated in / favorably situated', '[{"en":"The office is situated in the city center.","zh-TW":"辦公室位於市中心。"},{"en":"The company is well situated for growth.","zh-TW":"公司處於有利的成長位置。"}]', '{"noun":"situation","verb":"situate","adjective":"situated"}', NULL, 3, 6021, NULL),
(6022, 'six sigma', '/sɪks ˈsɪɡmə/', 'noun', '{"zh-TW":["六個標準差；六西格碼"],"en":["a data-driven methodology for eliminating defects in processes"]}', NULL, 'six sigma certification / implement six sigma', '[{"en":"Six sigma certification is highly valued in manufacturing.","zh-TW":"六個標準差認證在製造業非常有價值。"},{"en":"The six sigma project reduced error rates significantly.","zh-TW":"六個標準差項目顯著降低了錯誤率。"}]', NULL, NULL, 3, 6022, NULL),
(6023, 'size', '/saɪz/', 'noun', '{"zh-TW":["大小；規模","尺寸；大小"],"en":["how big or small something is","how large or small something is"]}', '{"root":{"text":"size","meaning":"measure (量度)"},"logic":"源自古法語 sise，指物品的量度。"}', 'market size / full-size; what size / size chart / one size fits all', '[{"en":"The market size is estimated at $5 billion.","zh-TW":"市場規模估計為50億美元。"},{"en":"What size do you need?","zh-TW":"你需要什麼尺寸？"},{"en":"What size do you wear?","zh-TW":"你穿什麼尺寸？"},{"en":"This shirt comes in three sizes.","zh-TW":"這件襯衫有三種尺寸。"}]', '{"noun":"size","adjective":"sizable","verb":"size","adjective2":"oversized"}', NULL, 1, 6023, NULL),
(6024, 'skeptical', '/ˈskeptɪkl/', 'adjective', '{"zh-TW":["懷疑的；持懷疑態度的"],"en":["not easily convinced; having doubts"]}', NULL, 'skeptical about / remain skeptical / highly skeptical', '[{"en":"Investors remain skeptical about the company''s recovery plan.","zh-TW":"投資者對公司的復甦計畫持懷疑態度。"},{"en":"She was skeptical of the proposal''s feasibility.","zh-TW":"她對提案的可行性持懷疑態度。"}]', '{"noun":"skepticism, skeptic","adjective":"skeptical"}', NULL, 3, 6024, NULL),
(6025, 'skepticism', '/ˈskeptɪsɪzəm/', 'noun', '{"zh-TW":["懷疑論；懷疑態度"],"en":["a doubting attitude toward claims"]}', NULL, 'healthy skepticism / meet with skepticism / express skepticism', '[{"en":"The proposal was met with skepticism from investors.","zh-TW":"該提案遭到投資者的質疑。"},{"en":"A healthy skepticism is important in business decisions.","zh-TW":"在商業決策中保持健康的懷疑態度很重要。"}]', '{"noun":"skepticism, skeptic","adjective":"skeptical"}', NULL, 4, 6025, NULL),
(6026, 'sketch', '/sketʃ/', 'noun', '{"zh-TW":["素描；草圖"],"en":["a rough drawing made quickly"]}', '{"root":{"text":"sketch","meaning":"quick drawing (速寫)"},"logic":"源自荷蘭語 schets（快速繪畫）。"}', 'pencil sketch / rough sketch', '[{"en":"She did a quick sketch of the building.","zh-TW":"她快速畫了一張建築物的草圖。"},{"en":"The designer showed us several sketches.","zh-TW":"設計師給我們看了幾張草圖。"}]', '{"verb":"sketch","adjective":"sketchy"}', NULL, 2, 6026, NULL),
