(6048, 'social capital', '/ˈsəʊʃəl ˈkæpɪtəl/', 'noun', '{"zh-TW":["社會資本"],"en":["networks and relationships between people that enable society to function effectively"]}', NULL, 'build social capital / social capital theory / erosion of social capital', '[{"en":"Communities with high social capital tend to have lower crime rates.","zh-TW":"具有高社會資本的社區往往犯罪率較低。"},{"en":"Trust is a key component of social capital in healthy societies.","zh-TW":"信任是健康社會中社會資本的關鍵組成部分。"}]', NULL, NULL, 5, 6048, NULL),
